create extension if not exists pgcrypto;
create table public.questions(id int primary key check(id between 1 and 20),section text not null,type text not null check(type in('single','multiple')),text text not null,options jsonb not null check(jsonb_typeof(options)='array'),correct jsonb not null check(jsonb_typeof(correct)='array'),explanation text not null,points numeric(3,1) not null default 1);
create table public.candidates(id uuid primary key default gen_random_uuid(),full_name text not null,agency text not null,email text,created_at timestamptz not null default now(),unique(full_name,agency));
create table public.attempts(id uuid primary key default gen_random_uuid(),candidate_id uuid not null references public.candidates(id) on delete cascade,user_id uuid not null references auth.users(id),status text not null default 'in_progress' check(status in('in_progress','submitted','expired')),started_at timestamptz not null default now(),expires_at timestamptz not null default now()+interval '30 minutes',submitted_at timestamptz,duration_sec int,score numeric(4,1),max_score numeric(4,1) not null default 20,passed boolean,level text check(level in('acquis','acquis_reserves','en_cours','non_acquis')),allow_retake boolean not null default false);
create table public.answers(id uuid primary key default gen_random_uuid(),attempt_id uuid not null references public.attempts(id) on delete cascade,question_id int not null references public.questions(id),selected jsonb not null default '[]'::jsonb check(jsonb_typeof(selected)='array'),is_correct boolean,is_partial boolean not null default false,points numeric(3,1) not null default 0,answered_at timestamptz not null default now(),unique(attempt_id,question_id));
create table public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,full_name text not null,role text not null default 'admin' check(role in('admin','viewer')),created_at timestamptz not null default now());
create index attempts_candidate_idx on public.attempts(candidate_id);create index attempts_status_submitted_idx on public.attempts(status,submitted_at desc);create index answers_question_idx on public.answers(question_id);create index candidates_agency_idx on public.candidates(agency);
